import{_ as e,o as t,c as a}from"./chunks/framework.D1Ss-Xl7.js";const h=JSON.parse('{"title":"Page 4 - notes | Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"notes/page/4","tag":"notes","title":"Page 4 - notes | Tag","prev":"/tags/notes/page/3/","next":null,"posts":[{"title":"安徽师范大学校园视频下载器2.0版本发布","url":"/posts/2013-03-15-ahnu-video-downloader/","date":"2013-03-15 15:30","tags":["notes"],"html":"<p>安师大的校园视频网是个资源不错但软件坑爹的东西.\\n当然这个服务不是安师大自己研发的,是由沈阳光音网视科技有限公司开发的,应该是学校出钱购买的吧.不过那个坑爹的客户端只给在线观看不给下载,\\n网页也是完美的兼容 IE6,Javascript 里面也调用了好多微软自己的 ActiveX 控件,所以只能用学校提供的自带的那个客户端浏览和观看视频.</p>\\n<p>对于这种反人类的做法我当然是很不爽了,客户端的网址栏虽然是不变的,不过是通过重定向的方式访问学校的服务器了吧,通过修改 hosts 我也可以直接在\\nIE 浏览器中查看,然后查看源代码进行了分析工作.原理其实很简单,就是通过解析服务器上的 XML 文件进行网页的渲染,XML 文件里面记录了服务器上所有的\\n视频资源和视频的 ID,然后通过一步步的研究直接找到了资源的下载地址.详细的原理请看我 github 上公开的<a href=\\"https://github.com/acgotaku/VideoSearch\\" target=\\"_blank\\" rel=\\"noreferrer\\">VideoSeach</a>\\n里面的 Function.cs 记录了具体解析过程.</p>\\n<p>通过研究知道了原理便和同学商量这开发个下载器方便大家使用,Win 版本是由同学基于.Net Framework 2.0 开发的,由于我的特殊需求变移植了\\nweb 版本,1.0 版本是在上学期开发并发布的.现在软件使用的用户大概有一万人左右,因为很多学校也用的这个视频服务提供商,我们变提供了配置按钮可以满足\\n各个学校的需求.不过寒假回来发现下载器不能再下载视频了,我便抽出一晚上时间研究了原因,发现是学校的服务器屏蔽了下载器的功能.手法也很简单使用\\nUser-Agent: Novasoft NetPlayer/4.0 进行屏蔽非官方客户端,知道原因事情就很简单了,伪造 UA 嘛,之前下载器是调用迅雷下载的,现在在里面内置了下载功能.</p>\\n<p>软件官网: <a href=\\"http://www.icehoney.me\\" target=\\"_blank\\" rel=\\"noreferrer\\">www.icehoney.me</a></p>\\n<p>百度云盘下载:<a href=\\"http://pan.baidu.com/share/link?shareid=457833&amp;uk=3021310168\\" target=\\"_blank\\" rel=\\"noreferrer\\">Download</a></p>\\n"},{"title":"个人博客的建立","url":"/posts/2013-02-07-start-blog/","date":"2013-02-07 22:07","tags":["notes"],"html":"<p>好吧,我建立个人博客的想法其实已经差不多有一年了吧.一直没去实现...主要原因还是自己太懒...一开始想用 WordPress 搭建一个....其实我也搭建了\\n但是由于一直找不到好看的主题就坑在那一年多了...后来还想用 Octopress 来搭建...又由于自己当时的系统是 Win 而放弃了,现在我把自己的系统换成\\nArch 并且在学习 Python,于是又开坑了...</p>\\n<p>虽然是自己动手写出来的,但基本属于山寨,毕竟现在自己对 Python 的掌握还属于初级阶段...UI 其实也是山寨的 &gt;_&gt;</p>\\n<p>嘛嘛,先搭建出来一个再说,之后自己再慢慢装饰吧,不过总算是把坑给填上了.万事开头难,迈出了第一步,之后就容易多了....</p>\\n<p>不过我这个文笔很差的人写的博客估计也没人看</p>\\n"}]},"relativePath":"tags/notes/page/4/index.md","filePath":"tags/[slug].md"}'),n={name:"tags/notes/page/4/index.md"};function r(o,s,p,i,l,c){return t(),a("div")}const d=e(n,[["render",r]]);export{h as __pageData,d as default};
